package forth

import (
	"errors"
	"strconv"
	"strings"
)

// Forth evaluates a sequence of Forth source lines and returns the
// resulting value stack, from bottom to top.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string][]string{}

	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) > 0 && tokens[0] == ":" {
			if err := define(words, tokens); err != nil {
				return nil, err
			}
			continue
		}
		var err error
		stack, err = run(stack, words, tokens)
		if err != nil {
			return nil, err
		}
	}
	return stack, nil
}

// define registers a new user word from a definition line of the form
// ": name definition ;". References to previously defined words are
// expanded at definition time so that later redefinitions do not affect
// words that were already defined.
func define(words map[string][]string, tokens []string) error {
	if len(tokens) < 4 || tokens[len(tokens)-1] != ";" {
		return errors.New("invalid definition")
	}
	name := strings.ToLower(tokens[1])
	if isNumber(name) {
		return errors.New("cannot redefine a number")
	}
	defn := make([]string, 0, len(tokens)-2)
	for _, tok := range tokens[2 : len(tokens)-1] {
		if sub, ok := words[strings.ToLower(tok)]; ok {
			defn = append(defn, sub...)
		} else {
			defn = append(defn, tok)
		}
	}
	words[name] = defn
	return nil
}

// run executes a list of tokens against the value stack.
func run(stack []int, words map[string][]string, tokens []string) ([]int, error) {
	for _, tok := range tokens {
		if isNumber(tok) {
			v, err := strconv.Atoi(tok)
			if err != nil {
				return nil, err
			}
			stack = append(stack, v)
			continue
		}
		key := strings.ToLower(tok)
		if def, ok := words[key]; ok {
			var err error
			stack, err = run(stack, words, def)
			if err != nil {
				return nil, err
			}
			continue
		}
		var err error
		stack, err = exec(stack, key)
		if err != nil {
			return nil, err
		}
	}
	return stack, nil
}

// exec executes one built-in word.
func exec(stack []int, word string) ([]int, error) {
	switch word {
	case "+", "-", "*", "/":
		if len(stack) < 2 {
			return nil, errors.New("insufficient values on the stack")
		}
		b, a := stack[len(stack)-2], stack[len(stack)-1]
		stack = stack[:len(stack)-2]
		switch word {
		case "+":
			stack = append(stack, a+b)
		case "-":
			stack = append(stack, b-a)
		case "*":
			stack = append(stack, a*b)
		default: // "/"
			if b == 0 {
				return nil, errors.New("division by zero")
			}
			stack = append(stack, b/a)
		}
	case "dup":
		if len(stack) == 0 {
			return nil, errors.New("empty stack")
		}
		stack = append(stack, stack[len(stack)-1])
	case "drop":
		if len(stack) == 0 {
			return nil, errors.New("empty stack")
		}
		stack = stack[:len(stack)-1]
	case "swap":
		if len(stack) < 2 {
			return nil, errors.New("insufficient values on the stack")
		}
		stack[len(stack)-2], stack[len(stack)-1] = stack[len(stack)-1], stack[len(stack)-2]
	case "over":
		if len(stack) < 2 {
			return nil, errors.New("insufficient values on the stack")
		}
		stack = append(stack, stack[len(stack)-2])
	default:
		return nil, errors.New("undefined word")
	}
	return stack, nil
}

// isNumber reports whether tok is a (possibly negative) integer literal:
// an optional '-' followed by one or more ASCII digits.
func isNumber(tok string) bool {
	if strings.HasPrefix(tok, "-") {
		tok = tok[1:]
	}
	if tok == "" {
		return false
	}
	for _, r := range tok {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

